clare: Quick TS draft:
// TS: 2 retries, honor Retry-After, then trim and fallback
async function gen(payload){
  for(let i=0;i<2;i++){
    const res = await fetch('/v1/generate',{method:'POST',body:JSON.stringify(payload)});
    if(res.status===200) return res.json();
    if(res.status===429){ const ra=res.headers.get('Retry-After'); await sleep(ra?Number(ra)*1000:Math.pow(2,i)*300); }
  }
  payload.input = trimKeepSystem(payload.input,2);
  return fetch('/v1/generate?model=small-1',{method:'POST',body:JSON.stringify(payload)}).then(r=>r.json());
}
mohit: Python variant (very short):
import time
def gen(client,prompt,primary,fallback):
  for i in range(2):
    r=client.generate(model=primary,prompt=prompt,timeout=5)
    if r.status==200: return r.text
    if r.status==429: time.sleep((2**i)*0.3)
  short='\n'.join(prompt.split('\n')[-3:])
  return client.generate(model=fallback,prompt=short).text
